#!/usr/bin/env bash
#
# Nightly backup of the Q-Basair user-data SQLite databases.
#
# Backs up the databases that hold IRREPLACEABLE user-generated content:
#   - auth.db        (accounts + sessions)
#   - app_data.db    (notebook, research sessions, followed roots, preferences)
# and, best-effort, the regenerable research index (research_agent.db).
# quran.db is intentionally NOT backed up — it is generated by build_db.py.
#
# Uses SQLite's online ".backup" for a consistent hot copy (safe while the API
# holds the DB open). Falls back to cp if the sqlite3 CLI is unavailable.
#
# Intended to run from cron on the production host, e.g.:
#   15 3 * * *  /srv/q-basair/scripts/backup_databases.sh >> /var/log/qbasair-backup.log 2>&1
#
# Env overrides:
#   QBASAIR_DATA_DIR      source dir holding the .db files   (default /srv/q-basair/data)
#   QBASAIR_BACKUP_DIR    destination root                   (default /srv/q-basair/backups)
#   QBASAIR_BACKUP_RETENTION_DAYS  delete backups older than N days (default 14)

set -euo pipefail

DATA_DIR="${QBASAIR_DATA_DIR:-/srv/q-basair/data}"
BACKUP_DIR="${QBASAIR_BACKUP_DIR:-/srv/q-basair/backups}"
RETENTION_DAYS="${QBASAIR_BACKUP_RETENTION_DAYS:-14}"

DATABASES="auth.db app_data.db research_agent.db"

timestamp="$(date +%Y%m%d-%H%M%S)"
dest="${BACKUP_DIR}/${timestamp}"
mkdir -p "${dest}"

backup_one() {
  local name="$1"
  local src="${DATA_DIR}/${name}"
  local out="${dest}/${name}"
  if [ ! -f "${src}" ]; then
    echo "skip: ${src} not found"
    return 0
  fi
  if command -v sqlite3 >/dev/null 2>&1; then
    # Consistent online backup — safe while the DB is open by the API.
    sqlite3 "${src}" ".backup '${out}'"
  else
    # Fallback: plain copy (small risk of an inconsistent snapshot under load).
    cp "${src}" "${out}"
  fi
  echo "backed up: ${name} -> ${out}"
}

for db in ${DATABASES}; do
  backup_one "${db}"
done

# Compress the snapshot dir to save space. Archiving is best-effort — a failure
# must never discard the good uncompressed copies already written above.
if command -v tar >/dev/null 2>&1; then
  if tar -czf "${dest}.tar.gz" -C "${BACKUP_DIR}" "${timestamp}"; then
    rm -rf "${dest}"
    echo "archived: ${dest}.tar.gz"
  else
    echo "warning: archiving failed; keeping uncompressed snapshot at ${dest}"
  fi
fi

# Prune old backups beyond the retention window.
find "${BACKUP_DIR}" -maxdepth 1 -name '*.tar.gz' -type f -mtime "+${RETENTION_DAYS}" -print -delete || true
find "${BACKUP_DIR}" -maxdepth 1 -type d -name '20*' -mtime "+${RETENTION_DAYS}" -exec rm -rf {} + 2>/dev/null || true

echo "backup complete: ${timestamp}"
